fix.code:
final class LruCache<K, V> {
    private final Map<K, V> map;

    LruCache(int capacity) {
        this.map = new LinkedHashMap<>(16, 0.75f, true) {   // true: thứ tự truy cập
            @Override
            protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
                return size() > capacity;
            }
        };
    }

    // get cũng đổi cấu trúc ở chế độ truy cập, nên cần cùng một khoá với put
    synchronized V get(K key)             { return map.get(key); }
    synchronized void put(K key, V value) { map.put(key, value); }
    synchronized Set<K> keys()            { return Set.copyOf(map.keySet()); }
}
